permit (
  principal,
  action == Taxpreparer::Action::"viewDocument",
  resource
)
when
{
  principal.assigned_orgs
    .contains
    (
      {
        organization: resource.owner.organization,
        serviceline: resource.serviceline,
        location: resource.location
      }
    )
};

permit (
  principal,
  action == Action::"ModifyDocument",
  resource
)
when { principal == resource.owner };

@id("template-edit for owner")
permit (
  principal,
  action in Action::"PrezEditActions",
  resource
)
when { resource.owner == principal };

permit (
  principal,
  action == Action::"push",
  resource
)
when { principal in resource.writers };

permit (
  principal == Public::"public",
  action == Action::"ViewDocument",
  resource
)
when { resource.publicAccess == "edit" }
unless { resource.isPrivate };

@id("market-template-view")
permit (
  principal,
  action in Action::"MarketTemplateViewActions",
  resource
)
when { principal in resource.viewerMarkets };

@id("readTemplate")
permit (
    principal in ?principal,
    action == Action::"read",
    resource == ?resource
);

@id("DoeFamily")
permit (
  principal in PhotoApp::UserGroup::"DoeFamily",
  action == PhotoApp::Action::"viewPhoto",
  resource in PhotoApp::Album::"DoePhotos"
);

@id("resource.contributors_Repo")
permit (
  principal,
  action in
    [GitApp::Action::"pushRepo",
     GitApp::Action::"pullRepo",
     GitApp::Action::"forkRepo"],
  resource in GitApp::Application::"GitApp"
)
when { resource has contributors && principal in resource.contributors };

permit (
  principal,
  action == Action::"assign_issue",
  resource
)
when { principal in resource.repo.triagers };

@id("template")
permit (
    principal in ?principal,
    action == Action::"read",
    resource in ?resource
);

@id("policy3")
permit(
    principal == User::"Alice_admin",
    action == Action::"Read",
    resource == Document::"confidential_doc1"
);

permit (
  principal,
  action == Action::"edit_issue",
  resource
)
when { principal in resource.repo.readers && principal == resource.reporter };

permit (
    principal,
    action in Action::"write",
    resource
)
when { principal in resource.owner.writers };

permit (
  principal == User::"alice",
  action,
  resource in Album::"jane_vacation"
);

@id("policy2")
forbid(
    principal == User::"Bob_admin",
    action == Action::"Read",
    resource == Document::"protected_doc1"
);

permit (
  principal,
  action in
    [Action::"viewReservation",
     Action::"updateReservation",
     Action::"createReservation",
     Action::"grantAccessReservation"

    ],
  resource
)
when
{
  resource in principal.hotelAdminPermissions ||
  resource in principal.propertyAdminPermissions
};

permit (
  principal in UserGroup::"jane_friends",
  action == Action::"view",
  resource == Photo::"VacationPhoto94.jpg"
);

permit (
  principal,
  action in [Action::"ModifyGroup", Action::"DeleteGroup"],
  resource
)
when { principal == resource.owner };

@id("policy14")
permit(
    principal == User::"Alice_admin",
    action == Action::"Delete",
    resource == DocumentGroup::"Public"
) when {
    context.authenticated == true &&
    context.delete_confirmation == true
};

permit (
    principal,
    action in Action::"maintain",
    resource
)
when { principal in resource.maintainers };

permit (
  principal,
  action == Action::"view",
  resource == Photo::"VacationPhoto94.jpg"
)
when { context.source_ip == ip("222.222.222.222") };

@id("policy0")
permit(
    principal in UserGroup::"Admin",
    action in Action::"Read",
    resource in DocumentGroup::"Protected"
);

permit (
  principal,
  action == Action::"view",
  resource in Album::"jane_vacation"
);

@id("resource.reporters")
permit (
  principal,
  action in
    [GitApp::Action::"pullRepo",
     GitApp::Action::"forkRepo",
     GitApp::Action::"addIssue"],
  resource in GitApp::Application::"GitApp"
)
when { resource has reporters && principal in resource.reporters };

permit (
    principal,
    action == Action::"read",
    resource
)
when { resource in principal.documentsAndFoldersWithViewAccess };

@id("subscriber-content-access/movie")
permit (
  principal is Subscriber,
  action == Action::"watch",
  resource is Movie
)
unless { resource.needsRentOrBuy };
